/// The gallery's example of `Sticky`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let section = |name: &'static str| {
            let rows: Vec<AnyView> =
                (1..=6).map(|n| Box::new(Text::new(format!("{name} {n}"))) as AnyView).collect();
            VStack::new((
                {
                    let mut it = Sticky::new(Badge::new(name).tone(Tone::Accent));
                    it
                },
                VStack::new(rows).spacing(8.0),
            ))
            .spacing(8.0)
        };
        ScrollView::new((section("Inputs"), section("Overlays"), section("Data"))).spacing(16.0).height(220.0)
    })
}

impl ComponentBook for Sticky<AnyView> {
    fn book() -> Meta {
        Meta::new("Layout/Sticky", render)
            .summary("Stays below the top while its section scrolls past.")
            .story("Example", Args::new())
    }
}
